/**
 * Dictionary Cache
 */
export class DictionaryCache {
    public dict: Uint8Array;
    private map: Map<string, number[]> = new Map();
    private readonly minMatch: number;
    private readonly maxMatch: number;

    /**
     * Create Cache Dictionary
     * @param dictionary {Uint8Array} Dictionary
     * @param minMatch {number}
     * @param maxMatch {number}
     */
    constructor(dictionary: Uint8Array, minMatch : number = 3, maxMatch : number = 18) {
        this.dict = dictionary;
        this.minMatch = minMatch;
        this.maxMatch = maxMatch;
        this.buildIndex();
    }

    /**
     * Build Index
     * @private
     */
    private buildIndex(): void {
        for (let pos = 0; pos < this.dict.length; pos++) {
            for (let len = this.minMatch; len <= this.maxMatch && pos + len <= this.dict.length; len++) {
                const hash = this.hash(this.dict.subarray(pos, pos + len));
                const positions = this.map.get(hash) || [];
                positions.push(pos);
                this.map.set(hash, positions);
            }
        }
    }

    /**
     * Hash
     * @param block {Uint8Array} Block
     * @returns {string} Hash
     * @private
     */
    private hash(block: Uint8Array): string {
        let h = 2166136261;
        for (let i = 0; i < block.length; i++) {
            h ^= block[i];
            h *= 16777619;
        }
        return h.toString(36);
    }

    /**
     * Find Match
     * @param data {Uint8Array} Data buffer
     * @param dataPos {number} Position
     * @returns {Object|null} Match or null
     */
    public findMatch(data: Uint8Array, dataPos: number): { offset: number; length: number } | null {
        let bestLen = 0;
        let bestOffset = 0;
        for (let len = this.maxMatch; len >= this.minMatch; len--) {
            if (dataPos + len > data.length) continue;
            const block = data.subarray(dataPos, dataPos + len);
            const hash = this.hash(block);
            const positions = this.map.get(hash);
            if (positions) {
                for (const dictPos of positions) {
                    let match = true;
                    for (let i = 0; i < len; i++) {
                        if (this.dict[dictPos + i] !== data[dataPos + i]) {
                            match = false;
                            break;
                        }
                    }
                    if (match && len > bestLen) {
                        bestLen = len;
                        bestOffset = dictPos;
                        if (bestLen === this.maxMatch) return { offset: bestOffset, length: bestLen };
                    }
                }
            }
        }
        return bestLen >= this.minMatch ? { offset: bestOffset, length: bestLen } : null;
    }
}